  "a_sentences": [
    {
      "a_text": "Le litige porte exclusivement sur le caractère abusif du licenciement signifié à l'intimée (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que l'employeur avait violé ses obligations de protection de la personnalité de l'intimée et n'avait pas pris les mesures attendues pour remédier aux conflits (P2 et P3).",
      "b_propositions": ["P2", "P3"]
    },
    {
      "a_text": "Le droit de résiliation est limité par les dispositions sur le congé abusif des art. 336 ss CO (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Un abus du droit de résiliation peut être admis dans d'autres situations comparables par leur gravité aux cas expressément visés par la loi (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale a jugé que le congé-modification était abusif car l'employeur avait exploité sa propre violation de l'obligation de protection pour imposer des conditions très défavorables à l'intimée (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la problématique ne réside pas dans la liberté de proposer une modification contractuelle, mais dans l'exploitation par l'employeur de sa violation des obligations de protection pour imposer une modification très défavorable (P7).",
      "b_propositions": ["P7"]
    }
  ]
}
